-- A SKU identifies an inventory row. Quantity is a nonnegative integer.
CREATE TABLE IF NOT EXISTS inventory (
    sku TEXT PRIMARY KEY NOT NULL,
    qty INTEGER NOT NULL CHECK (typeof(qty) = 'integer' AND qty >= 0)
);
-- An idempotency key identifies one original request, not a SKU.
CREATE TABLE IF NOT EXISTS orders (
    request_key TEXT PRIMARY KEY NOT NULL,
    sku TEXT NOT NULL REFERENCES inventory(sku),
    qty INTEGER NOT NULL CHECK (typeof(qty) = 'integer' AND qty > 0),
    stock_left INTEGER NOT NULL
);
INSERT OR IGNORE INTO inventory(sku, qty) VALUES ('A', 5);

"""Persist one inventory deduction and its receipt in the same transaction."""
from contextlib import closing
from pathlib import Path
import sqlite3


def connect(db):
    conn = sqlite3.connect(db, timeout=2, isolation_level=None)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db(db):
    with closing(connect(db)) as conn:
        conn.execute("PRAGMA journal_mode = WAL")
        conn.executescript(Path(__file__).with_name("schema.sql").read_text(encoding="utf-8"))


def place_order(db, request_key, sku, qty):
    """Return (HTTP status, receipt); API validates input first."""
    if not isinstance(request_key, str) or not request_key or not isinstance(sku, str) or not sku or type(qty) is not int or qty <= 0:
        return 400, {"error": "invalid_order"}
    with closing(connect(db)) as conn:
        # Take the write lock before reading the idempotency key, so two
        # concurrent requests cannot both decide the key is unused.
        conn.execute("BEGIN IMMEDIATE")
        try:
            prior = conn.execute("SELECT * FROM orders WHERE request_key=?", (request_key,)).fetchone()
            if prior is not None:
                conn.rollback()
                if prior["sku"] != sku or prior["qty"] != qty:
                    return 409, {"error": "key_conflict"}
                return 200, {**dict(prior), "replayed": True}
            updated = conn.execute("UPDATE inventory SET qty=qty-? WHERE sku=? AND qty>=?", (qty, sku, qty))
            if updated.rowcount != 1:
                found = conn.execute("SELECT 1 FROM inventory WHERE sku=?", (sku,)).fetchone()
                conn.rollback()
                return (409, {"error": "insufficient_stock"}) if found else (404, {"error": "unknown_sku"})
            remaining = conn.execute("SELECT qty FROM inventory WHERE sku=?", (sku,)).fetchone()["qty"]
            receipt = dict(request_key=request_key, sku=sku, qty=qty, stock_left=remaining)
            conn.execute("INSERT INTO orders(request_key,sku,qty,stock_left) VALUES (?, ?, ?, ?)", tuple(receipt.values()))
            conn.commit()
            return 201, {**receipt, "replayed": False}
        except BaseException:
            conn.rollback()
            raise

"""Small HTTP adapter. No cluster credentials are available to this service."""
import json
import os
import sqlite3
from pathlib import Path

from service import init_db, place_order

MAX_BODY = 4096


def dispatch(method, path, headers, body, db):
    if method == "GET" and path in {"/live", "/ready"}:
        # The previous chapters are testable before health.py exists.
        from health import health_result
        return health_result(path, db)
    if path != "/orders":
        return 404, {"error": "not_found"}
    if method != "POST":
        return 405, {"error": "method_not_allowed"}
    if len(body) > MAX_BODY:
        return 413, {"error": "body_too_large"}
    key = headers.get("Idempotency-Key", "")
    if not isinstance(key, str) or not (1 <= len(key) <= 80) or not key.isascii() or not all(c.isalnum() or c in "-_." for c in key):
        return 400, {"error": "invalid_key"}
    try:
        value = json.loads(body)
    except (UnicodeError, ValueError, RecursionError):
        return 400, {"error": "invalid_json"}
    if not isinstance(value, dict):
        return 400, {"error": "invalid_order"}
    sku, qty = value.get("sku"), value.get("qty")
    if not isinstance(sku, str) or not 1 <= len(sku) <= 64 or type(qty) is not int or not 1 <= qty <= 10000:
        return 400, {"error": "invalid_order"}
    try:
        return place_order(db, key, sku, qty)
    except sqlite3.OperationalError:
        return 503, {"error": "temporarily_unavailable"}


def serve(db, host="127.0.0.1", port=8080):
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

    init_db(db)

    class Handler(BaseHTTPRequestHandler):
        def handle_order(self):
            self.connection.settimeout(5)
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                length = -1
            if length < 0 or self.headers.get("Transfer-Encoding"):
                self.send_error(400)
                return
            if length > MAX_BODY:
                self.send_error(413)
                return
            try:
                data = self.rfile.read(length)
            except TimeoutError:
                self.send_error(408)
                return
            if len(data) != length:
                self.send_error(400)
                return
            status, payload = dispatch(self.command, self.path, self.headers, data, db)
            encoded = json.dumps(payload).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(encoded)))
            self.end_headers()
            self.wfile.write(encoded)

        do_GET = do_POST = handle_order

    with ThreadingHTTPServer((host, port), Handler) as server:
        server.serve_forever()


if __name__ == "__main__":
    db = Path(os.environ.get("ORDER_DB", "orders.db"))
    serve(db, os.environ.get("ORDER_HOST", "127.0.0.1"), int(os.environ.get("ORDER_PORT", "8080")))

